#include <bits/stdc++.h>
using namespace std;
struct Node {
    int l = 0, r = 0, sz = 1, val;
    unsigned pri;
    bool rev = false;
} t[500005];
unsigned seedv = 712367821;
unsigned rng() {
    seedv ^= seedv << 13;
    seedv ^= seedv >> 17;
    return seedv ^= seedv << 5;
}
int sz(int x) { return x ? t[x].sz : 0; }
void pull(int x) {
    if (x) t[x].sz = 1 + sz(t[x].l) + sz(t[x].r);
}
void flip(int x) {
    if (x) swap(t[x].l, t[x].r), t[x].rev ^= 1;
}
void push(int x) {
    if (x && t[x].rev) flip(t[x].l), flip(t[x].r), t[x].rev = false;
}
int merge_t(int a, int b) {
    if (!a || !b) return a | b;
    if (t[a].pri < t[b].pri) {
        push(a);
        t[a].r = merge_t(t[a].r, b);
        pull(a);
        return a;
    }
    push(b);
    t[b].l = merge_t(a, t[b].l);
    pull(b);
    return b;
}
void split(int x, int k, int &a, int &b) {
    if (!x) {
        a = b = 0;
        return;
    }
    push(x);
    if (sz(t[x].l) >= k) {
        split(t[x].l, k, a, t[x].l);
        b = x;
        pull(b);
    } else {
        split(t[x].r, k - sz(t[x].l) - 1, t[x].r, b);
        a = x;
        pull(a);
    }
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    while (cin >> n >> q) {
        vector<int> root(n + 1);
        int tot = 0;
        while (q--) {
            int op, u, v, w, val, a, b;
            cin >> op;
            if (op == 1) {
                cin >> u >> w >> val;
                ++tot;
                t[tot] = Node();
                t[tot].val = val;
                t[tot].pri = rng();
                if (w == 0)
                    root[u] = merge_t(tot, root[u]);
                else
                    root[u] = merge_t(root[u], tot);
            } else if (op == 2) {
                cin >> u >> w;
                if (!root[u]) {
                    cout << -1 << '\n';
                    continue;
                }
                if (w == 0) {
                    split(root[u], 1, a, b);
                    root[u] = b;
                } else {
                    split(root[u], sz(root[u]) - 1, b, a);
                    root[u] = b;
                }
                cout << t[a].val << '\n';
            } else {
                cin >> u >> v >> w;
                if (w) flip(root[v]);
                root[u] = merge_t(root[u], root[v]);
                root[v] = 0;
            }
        }
    }
}

