        while (!q.empty()) {
            int u = q.front();
            q.pop();
            for (auto [v, w] : g[u])
                if (v != up[0][u])
                    up[0][v] = u, dep[v] = dep[u] + 1, dist[v] = dist[u] + w, q.push(v);
        }
        for (int j = 1; j < L; j++)
            for (int i = 1; i <= n; i++) up[j][i] = up[j - 1][up[j - 1][i]];
