#include <algorithm>
#include <cstdio>

const int integer_num_max = 100000, OPERATION_NUM_MAX = 100000;

struct SegmentTreeNode {
    int begin, end;
    long long sum, increment;
};

int integer_num, operation_num;
int integers[integer_num_max];
SegmentTreeNode segment_tree[integer_num_max * 3];

int left_son(int index) { return 2 * index + 1; }

int right_son(int index) { return 2 * index + 2; }

void create_segment_tree(int index, int begin, int end) {
    segment_tree[index].begin = begin;
    segment_tree[index].end = end;
    if (begin + 1 == end)
        segment_tree[index].sum = integers[begin];
    else {
        int mid = (begin + end) / 2;
        create_segment_tree(left_son(index), begin, mid);
        create_segment_tree(right_son(index), mid, end);
        segment_tree[index].sum =
            segment_tree[left_son(index)].sum + segment_tree[right_son(index)].sum;
    }
    segment_tree[index].increment = 0;
}

long long sum(int index, int begin, int end) {
    if (begin >= segment_tree[index].end || end <= segment_tree[index].begin) return 0;
    if (begin <= segment_tree[index].begin && end >= segment_tree[index].end)
        return segment_tree[index].sum;

    int section_begin = std::max(begin, segment_tree[index].begin),
        section_end = std::min(end, segment_tree[index].end);
    long long increment_total = (section_end - section_begin) * segment_tree[index].increment;
    return sum(left_son(index), begin, end) + sum(right_son(index), begin, end) + increment_total;
}

long long query(int begin, int end) { return sum(0, begin, end); }

void increase(int index, int begin, int end, int increment) {
    if (begin >= segment_tree[index].end || end <= segment_tree[index].begin) return;

    int section_begin = std::max(begin, segment_tree[index].begin),
        section_end = std::min(end, segment_tree[index].end);
    segment_tree[index].sum += (section_end - section_begin) * increment;

    if (begin <= segment_tree[index].begin && end >= segment_tree[index].end) {
        segment_tree[index].increment += increment;
        return;
    }
    increase(left_son(index), begin, end, increment);
    increase(right_son(index), begin, end, increment);
}

void add(int begin, int end, int increment) { increase(0, begin, end, increment); }

int main() {
    scanf("%d%d", &integer_num, &operation_num);
    for (int integer_index = 0; integer_index < integer_num; integer_index++)
        scanf("%d", integers + integer_index);
    create_segment_tree(0, 0, integer_num);
    while (operation_num--) {
        char operation_type;
        scanf(" %c", &operation_type);
        if (operation_type == 'Q') {
            int lower, upper;
            scanf("%d%d", &lower, &upper);
            printf("%lld\n", query(lower - 1, upper));
        } else if (operation_type == 'C') {
            int lower, upper, increment;
            scanf("%d%d%d", &lower, &upper, &increment);
            add(lower - 1, upper, increment);
        }
    }
    return 0;
}

