#include <algorithm>
#include <cstdio>

struct Snowflake {
    int arm_len[6];
};

const int hash_max = 1000000, EMPTY = -1;

int hash(const Snowflake& snowflake) {
    int sum = 0;
    for (int arm_index = 0; arm_index < 6; arm_index++) sum += snowflake.arm_len[arm_index];
    return sum % hash_max;
}

bool equals(const Snowflake& left, const Snowflake& right) {
    for (int shift = 0; shift < 6; shift++) {
        int same = true;
        for (int arm_index = 0; arm_index < 6; arm_index++)
            if (left.arm_len[arm_index] != right.arm_len[(arm_index + shift) % 6]) same = false;
        if (same) return true;
        same = true;
        for (int arm_index = 0; arm_index < 6; arm_index++)
            if (left.arm_len[arm_index] != right.arm_len[(5 - arm_index + shift) % 6]) same = false;
        if (same) return true;
    }
    return false;
}

bool twins_exist(int exist_index, int new_index, Snowflake snowflakes[], int next[]) {
    if (equals(snowflakes[exist_index], snowflakes[new_index])) return true;
    if (next[exist_index] == EMPTY) {
        next[exist_index] = new_index;
        return false;
    }
    return twins_exist(next[exist_index], new_index, snowflakes, next);
}

int main() {
    int snowflake_num;
    scanf("%d", &snowflake_num);
    Snowflake* snowflakes = new Snowflake[snowflake_num];
    int* hash_table = new int[hash_max];
    std::fill(hash_table, hash_table + hash_max, EMPTY);
    int* next = new int[snowflake_num];
    std::fill(next, next + snowflake_num, EMPTY);
    bool twin_found = false;
    for (int snowflake_index = 0; snowflake_index < snowflake_num; snowflake_index++) {
        for (int arm_index = 0; arm_index < 6; arm_index++)
            scanf("%d", snowflakes[snowflake_index].arm_len + arm_index);
        if (twin_found) continue;
        int hash_code = hash(snowflakes[snowflake_index]);
        if (hash_table[hash_code] == EMPTY)
            hash_table[hash_code] = snowflake_index;
        else
            twin_found = twins_exist(hash_table[hash_code], snowflake_index, snowflakes, next);
    }
    if (twin_found)
        printf("Twin snowflakes found.\n");
    else
        printf("No two snowflakes are alike.\n");
    delete[] next;
    delete[] hash_table;
    delete[] snowflakes;
    return 0;
}

