#include <bits/stdc++.h>
using namespace std;
struct N {
    int l = 0, r = 0, s = 1, v;
    unsigned p;
    bool rev = false;
} t[600005];
unsigned z = 123456789;
unsigned rnd() {
    z ^= z << 13;
    z ^= z >> 17;
    return z ^= z << 5;
}
int S(int x) { return x ? t[x].s : 0; }
void P(int x) {
    if (x) t[x].s = S(t[x].l) + S(t[x].r) + 1;
}
void R(int x) {
    if (x) swap(t[x].l, t[x].r), t[x].rev ^= 1;
}
void D(int x) {
    if (x && t[x].rev) R(t[x].l), R(t[x].r), t[x].rev = 0;
}
int M(int a, int b) {
    if (!a || !b) return a | b;
    if (t[a].p < t[b].p) {
        D(a);
        t[a].r = M(t[a].r, b);
        P(a);
        return a;
    }
    D(b);
    t[b].l = M(a, t[b].l);
    P(b);
    return b;
}
void Q(int x, int k, int& a, int& b) {
    if (!x) {
        a = b = 0;
        return;
    }
    D(x);
    if (S(t[x].l) >= k)
        Q(t[x].l, k, a, t[x].l), b = x, P(b);
    else
        Q(t[x].r, k - S(t[x].l) - 1, t[x].r, b), a = x, P(a);
}
void out(int x, vector<int>& a) {
    if (!x) return;
    D(x);
    out(t[x].l, a);
    a.push_back(t[x].v);
    out(t[x].r, a);
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    while (cin >> n >> m && n >= 0 && m >= 0) {
        int root = 0;
        for (int i = 1; i <= n; i++) {
            t[i] = N();
            t[i].v = i;
            t[i].p = rnd();
            root = M(root, i);
        }
        while (m--) {
            string op;
            int a, b, c, x, y, w;
            cin >> op >> a >> b;
            if (op[0] == 'C') {
                cin >> c;
                Q(root, b, x, w);
                Q(x, a - 1, x, y);
                root = M(x, w);
                Q(root, c, x, w);
                root = M(M(x, y), w);
            } else {
                Q(root, b, x, w);
                Q(x, a - 1, x, y);
                R(y);
                root = M(M(x, y), w);
            }
        }
        vector<int> a;
        out(root, a);
        for (int i = 0; i < n; i++) cout << a[i] << (i + 1 == n ? '\n' : ' ');
    }
}

