#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll inf = (1LL << 60);
struct N {
    int l = 0, r = 0, s = 1;
    ll v = 0, mn = 0, add = 0;
    unsigned p = 0;
    bool rev = false;
} t[300005];
unsigned z = 2463534242u;
unsigned rnd() {
    z ^= z << 13;
    z ^= z >> 17;
    return z ^= z << 5;
}
int S(int x) { return x ? t[x].s : 0; }
ll MN(int x) { return x ? t[x].mn : inf; }
void P(int x) {
    if (x) t[x].s = S(t[x].l) + S(t[x].r) + 1, t[x].mn = min(t[x].v, min(MN(t[x].l), MN(t[x].r)));
}
void A(int x, ll d) {
    if (x) t[x].v += d, t[x].mn += d, t[x].add += d;
}
void R(int x) {
    if (x) swap(t[x].l, t[x].r), t[x].rev ^= 1;
}
void D(int x) {
    if (!x) return;
    if (t[x].add) A(t[x].l, t[x].add), A(t[x].r, t[x].add), t[x].add = 0;
    if (t[x].rev) R(t[x].l), R(t[x].r), t[x].rev = 0;
}
int M(int a, int b) {
    if (!a || !b) return a | b;
    if (t[a].p < t[b].p) {
        D(a);
        t[a].r = M(t[a].r, b);
        P(a);
        return a;
    }
    D(b);
    t[b].l = M(a, t[b].l);
    P(b);
    return b;
}
void Q(int x, int k, int& a, int& b) {
    if (!x) {
        a = b = 0;
        return;
    }
    D(x);
    if (S(t[x].l) >= k)
        Q(t[x].l, k, a, t[x].l), b = x, P(b);
    else
        Q(t[x].r, k - S(t[x].l) - 1, t[x].r, b), a = x, P(a);
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    if (!(cin >> n)) return 0;
    int root = 0, tot = 0;
    auto node = [&](ll v) {
        ++tot;
        t[tot] = N();
        t[tot].v = t[tot].mn = v;
        t[tot].p = rnd();
        return tot;
    };
    for (int i = 0; i < n; i++) {
        ll v;
        cin >> v;
        root = M(root, node(v));
    }
    int q;
    cin >> q;
    while (q--) {
        string op;
        int x, y, a, b, c;
        ll d;
        cin >> op;
        if (op == "INSERT") {
            cin >> x >> d;
            Q(root, x, a, b);
            root = M(M(a, node(d)), b);
        } else if (op == "DELETE") {
            cin >> x;
            Q(root, x, a, c);
            Q(a, x - 1, a, b);
            root = M(a, c);
        } else {
            cin >> x >> y;
            Q(root, y, a, c);
            Q(a, x - 1, a, b);
            if (op == "ADD")
                cin >> d, A(b, d);
            else if (op == "REVERSE")
                R(b);
            else if (op == "MIN")
                cout << MN(b) << '\n';
            else {
                cin >> d;
                int len = y - x + 1, k = (int)((d % len + len) % len);
                if (k) {
                    int u, v;
                    Q(b, len - k, u, v);
                    b = M(v, u);
                }
            }
            root = M(M(a, b), c);
        }
    }
}

