#include <algorithm>
#include <cstdio>

const int field_num_max = 500, PATH_NUM_MAX = 2500, WORMHOLE_NUM_MAX = 200,
          DISTANCE_MAX = 100000000;

struct Edge {
    int from, to, weight;
};

bool bellman_ford(int vertex_num, int source, int edge_num, Edge edges[]) {
    int distances[field_num_max];
    std::fill(distances, distances + vertex_num, DISTANCE_MAX);
    distances[source] = 0;
    for (int i = 0; i < vertex_num; i++) {
        for (int edge_id = 0; edge_id < edge_num; edge_id++)
            if (distances[edges[edge_id].to] >
                distances[edges[edge_id].from] + edges[edge_id].weight)
                distances[edges[edge_id].to] =
                    distances[edges[edge_id].from] + edges[edge_id].weight;
    }
    for (int edge_id = 0; edge_id < edge_num; edge_id++)
        if (distances[edges[edge_id].to] > distances[edges[edge_id].from] + edges[edge_id].weight)
            return false;
    return true;
}

int main() {
    int farm_num;
    scanf("%d", &farm_num);
    while (farm_num--) {
        int field_num, path_num, wormhole_num;
        scanf("%d%d%d", &field_num, &path_num, &wormhole_num);
        int vertex_num = field_num, edge_num = 2 * path_num + wormhole_num;
        Edge edges[2 * PATH_NUM_MAX + WORMHOLE_NUM_MAX];
        int edge_id = 0;
        while (path_num-- > 0) {
            scanf("%d%d%d", &edges[edge_id].from, &edges[edge_id].to, &edges[edge_id].weight);
            /*
            edges[edgeID+1].from=edges[edgeID].to;
            edges[edgeID+1].to=edges[edgeID].from;
            edges[edgeID+1].weight=edges[edgeID].weight;
            */
            edges[edge_id + 1] = edges[edge_id];
            std::swap(edges[edge_id + 1].from, edges[edge_id + 1].to);
            edge_id += 2;
        }
        while (wormhole_num-- > 0) {
            scanf("%d%d%d", &edges[edge_id].from, &edges[edge_id].to, &edges[edge_id].weight);
            edges[edge_id].weight *= -1;
            edge_id++;
        }
        for (edge_id = 0; edge_id < edge_num; edge_id++) {
            edges[edge_id].from--;
            edges[edge_id].to--;
        }
        printf("%s\n", bellman_ford(vertex_num, 0, edge_num, edges) ? "NO" : "YES");
    }
    return 0;
}

