// #define DEBUG

void analyze_possibility(bool possible[10], const int row, const int col, const int board[9][9]) {
    fill(possible, possible + 10, true);
    for (int i = 0; i < 9; i++) possible[board[row][i]] = possible[board[i][col]] = false;
    int small_row = row / 3, small_col = col / 3;
    for (int i = small_row * 3; i < small_row * 3 + 3; i++)
        for (int j = small_col * 3; j < small_col * 3 + 3; j++) possible[board[i][j]] = false;
}

bool fill_board(int board[9][9], const int position) {
    if (position >= 9 * 9) return true;
    int row = position / 9, col = position % 9;
    if (board[row][col] != 0) return fill_board(board, position + 1);
    bool possible[10];
    analyze_possibility(possible, row, col, board);
    for (int i = 1; i <= 9; i++)
        if (possible[i]) {
            board[row][col] = i;
            if (fill_board(board, position + 1)) return true;
        }
    board[row][col] = 0;
    return false;
}

