bool ok(int x, int y) {
    if (x < 0 || x >= n || y < 0 || y >= m || a[x][y] == 'X') return 0;
    for (auto p : z)
        if (abs(x - p.x) + abs(y - p.y) <= 2 * tim) return 0;
    return 1;
}
bool go(queue<P>& q, int k, char me, char he) {
    while (k--) {
        int s = q.size();
        while (s--) {
            P u = q.front();
            q.pop();
            if (!ok(u.x, u.y)) continue;
            for (int d = 0; d < 4; d++) {
                int x = u.x + dx[d], y = u.y + dy[d];
                if (!ok(x, y) || a[x][y] == me) continue;
                if (a[x][y] == he) return 1;
                a[x][y] = me;
                q.push({x, y});
            }
        }
    }
    return 0;
}
