#include <bits/stdc++.h>
using namespace std;
int fac[10];
int rankp(const array<char, 9>& a) {
    int r = 0;
    for (int i = 0; i < 9; i++) {
        int c = 0;
        for (int j = i + 1; j < 9; j++) c += a[j] < a[i];
        r += c * fac[8 - i];
    }
    return r;
}
struct State {
    array<char, 9> a;
    int zero, id;
};
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    fac[0] = 1;
    for (int i = 1; i <= 9; i++) fac[i] = fac[i - 1] * i;
    vector<int> par(fac[9], -2);
    vector<char> mv(fac[9]);
    array<char, 9> goal = {'1', '2', '3', '4', '5', '6', '7', '8', '0'};
    int gid = rankp(goal);
    par[gid] = -1;
    queue<State> q;
    q.push({goal, 8, gid});
    int dx[4] = {-1, 1, 0, 0}, dy[4] = {0, 0, -1, 1};
    char back[4] = {'d', 'u', 'r', 'l'};
    while (!q.empty()) {
        auto s = q.front();
        q.pop();
        int x = s.zero / 3, y = s.zero % 3;
        for (int k = 0; k < 4; k++) {
            int nx = x + dx[k], ny = y + dy[k];
            if (nx < 0 || nx >= 3 || ny < 0 || ny >= 3) continue;
            auto a = s.a;
            int nz = nx * 3 + ny;
            swap(a[s.zero], a[nz]);
            int id = rankp(a);
            if (par[id] == -2) par[id] = s.id, mv[id] = back[k], q.push({a, nz, id});
        }
    }
    char c;
    while (cin >> c) {
        array<char, 9> a;
        a[0] = c == 'x' ? '0' : c;
        for (int i = 1; i < 9; i++) {
            cin >> c;
            a[i] = c == 'x' ? '0' : c;
        }
        int id = rankp(a);
        if (par[id] == -2)
            cout << "unsolvable\n";
        else {
            while (id != gid) {
                cout << mv[id];
                id = par[id];
            }
            cout << '\n';
        }
    }
}

