                   greater<pair<long long, int>>>
        dq;
    d[T] = 0;
    dq.push({0, T});
    while (dq.size()) {
        auto [du, u] = dq.top();
        dq.pop();
        if (du != d[u]) continue;
        for (auto [v, w] : r[u])
            if (d[v] > du + w) d[v] = du + w, dq.push({d[v], v});
    }
    if (d[S] == i) {
        cout << -1 << '\n';
        return 0;
    }
    if (S == T) K++;
